svg.script:
declare namespace svg="http://www.w3.org/2000/svg"; declare namespace xlink="http://www.w3.org/1999/xlink"; declare namespace chain="http://mansoft.nl/chain";
declare function local:process-field($row, $column, $field ) { let $x := ($column - 1) * 10 + 1 , $y := ($row - 1) * 10 + 1 return if (empty($field)) then <use xmlns="http://www.w3.org/2000/svg" xlink:href="#empty" x="{$x}" y="{$y}"/> else <use xmlns="http://www.w3.org/2000/svg" xlink:href="{concat('#', $field/@shape)}" x="{$x}" y="{$y}" fill="{$field/@color}" color="{if ($field/@state = 'current') then 'black' else if ($field/@state = 'visited') then 'white' else $field/@color}" chain:row="{$row}" chain:column="{$column}"/> };
declare function local:get-level() { let $search := b:getLocation("search") return if (starts-with($search, '?level=')) then substring($search, 8) else 1 };
declare variable $leveldoc := doc(concat('chain-level', local:get-level(), '.xml'));
declare %updating function local:click-svg($use, $evtObj) { if (not(empty($use/@chain:row)) and not(empty($use/@chain:column))) then ( let $field := $leveldoc/chain:chain-game/chain:field , $unvisited := $field[@state = 'unvisited'] , $new-field := $field[@row = $use/@chain:row][@column = $use/@chain:column] , $current-field := $field[@state = 'current'] , $current-row := $current-field/@row , $current-col := $current-field/@column , $new-row := $new-field/@row , $new-col := $new-field/@column , $current-svg-color := $use/../svg:use[@chain:row = $current-row][@chain:column = $current-col]/@color , $new-svg-color := $use/@color
return if ($new-field/@state = 'current') then b:alert('Same position') else if ($new-row != $current-row and $new-col != $current-col) then b:alert('Bad move: Stay in row or column') else if ($new-field/@state = 'visited') then b:alert('Bad move: Already been there') else if ($new-field/@shape != $current-field/@shape and $new-field/@color != $current-field/@color) then b:alert('Bad move: Must match colour or shape') else ( if (count($unvisited) = 1) then b:alert('Solved!') else (), replace value of node $current-field/@state with 'visited', replace value of node $new-field/@state with 'current', replace value of node $current-svg-color with 'white', replace value of node $new-svg-color with 'black', ) ) else () };
declare %updating function local:load-svg($svg, $evtObj) { let $chainreaction := $leveldoc/chain:chain-game , $chain-field := $leveldoc/chain:chain-game/chain:field , $columns := xs:integer($chainreaction/@columns) , $rows := xs:integer($chainreaction/@rows) return ( replace value of node $svg/@viewBox with concat("0 0 ", $columns * 10 + 2, " ", $rows * 10 + 2), b:log(b:getLocation("href")), ( for $row in 1 to $rows, $column in 1 to $columns let $field := $chain-field[xs:integer(@row) = $row][xs:integer(@column) = $column] , $use := local:process-field($row, $column, $field) return insert node $use as last into $svg ) ) }; b:addEventListener(b:dom()//svg:svg, "load", local:load-svg#2), b:addEventListener(b:dom()//svg:svg, "click", local:click-svg#2)
